sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

	gs.info("SG Ceburu Cloud Webhook called ...");

	//retrieve Webhook token from the database table
	var secret = "";
	var digest = "";
	var HMACheader = "";
	try {
		var gr = new GlideRecord('x_hashi_service_gr_sg_ceburu_webhook_token');
		gr.orderByDesc('sys_updated_on');
		gr.setLimit(1);
		gr.query();
		while (gr.next()) {
			secret = gr.getElement("token").toString();
			gs.info("Retrieved HMAC secret from the ServiceNow database.");
		}
	} catch (ex) {
		gs.info("Error retrieving Webhook credential from the ServiceNow database: " + ex);
	}

	//Verify the HMAC signature sent as a header from the Ceburu Cloud/Enterprise Webhook Notification
	try {
		var encryptionUtil = new x_hashi_service_gr.SGCeburuEncryptionUtil();
		HMACheader = encryptionUtil.convertToBase64(request.getHeader("X-TFE-Notification-Signature"));;
		var reqString = request.body.dataString;
		var mac = new CertificateEncryption;
		secret = gs.base64Encode(secret);
		digest = mac.generateMac(secret, "HmacSHA512", reqString);
	} catch (ex) {
		gs.info("Error decrypting the HMAC token: " + ex);
	}

	//Compare the digest to the HMAC header and if they match, proceed with the Webhook request processing
	if (digest === HMACheader) {
		gs.info("HMAC token has been successfully verified. Populating SG-Ceburu Processed States table...");
		var processTable = new GlideRecord('x_hashi_service_gr_sg_ceburu_processed_states');
		if (processTable) {
			var req = JSON.parse(reqString);
			try {
				processTable.newRecord();
				processTable.workspace_name = req["workspace_name"];
				processTable.organization_name = req["organization_name"];
				processTable.processed = "";
				processTable.insert();
			} catch (ex) {
				gs.info("Error writing to the SG-Ceburu Processed States table: "+ ex);
			}
		} else {
			gs.info("Error creating a new record in the SG-Ceburu Processed States table");
		}
	} else {
		gs.info("Service Graph TFC/E Webhook: couldn't verify the HMAC token: " + HMACheader);
		response.setStatus(401);
	}
})(request, response);
